        if (mobile) {
            const flightSummary = renderFlightSummary({
                origin: my_data['origen_ciudad'],
                destination: my_data['destino_ciudad'],
                startDate: my_data['fecha_ida'],
                endDate: my_data['fecha_vuelta'] || '',
                pax: Object.values(JSON.parse(my_data['pasajeros'])).reduce((acc, val) => acc + val, 0)
            });
            $('#flightSummary').html(flightSummary);
        }


        var totalVuelo = 0;
        var totalPasajeros = 1;
        try {
            const pasajeros = JSON.parse(my_data['pasajeros'] || "{}");
            const calculatedPasajeros =
                (pasajeros.adultos || 0) +
                (pasajeros.ninos || 0);
            // (pasajeros.bebes || 0);
            totalPasajeros = calculatedPasajeros > 0 ? calculatedPasajeros : 1;
            $('#numPasajeros').text(totalPasajeros);
        } catch (e) {
            console.warn("Error al parsear pasajeros:", e);
        }

        console.log('DEBUG resumen.php - v1_precio:', my_data['v1_precio'], 'v2_precio:', my_data['v2_precio']);

        if (my_data['v1_precio']) {
            const v1 = parseInt(my_data['v1_precio'].replace(/\./g, ""), 10) || 0;
            totalVuelo += v1;
        }

        if (my_data['v2_precio']) {
            const v2 = parseInt(my_data['v2_precio'].replace(/\./g, ""), 10) || 0;
            totalVuelo += v2;
        }

        totalVuelo *= totalPasajeros;
        var totalVueloConAumento = totalVuelo;
        var totalVueloFormateado = totalVuelo.toLocaleString("es-CO");
        var totalFormateado = totalVueloConAumento.toLocaleString("es-CO");

        // Mostrar en el DOM
